def letter_frequency_analysis(ciphertext: str) -> dict:
    # Initialize a dictionary with all letters set to 0
    freq_dict = {chr(i): 0 for i in range(ord('a'), ord('z')+1)}

    # Convert the ciphertext to lowercase to make it case-insensitive
    ciphertext = ciphertext.lower()

    # Count the frequency of each letter
    for char in ciphertext:
